def solve(n, a):
    # Find the largest power of 2 that is less than or equal to n
    m = 0
    while 2**m <= n:
        m += 1

    # Sort the array in non-decreasing order
    for i in range(1, m):
        for j in range(i, 2**m):
            a[j] -= 1

    # Check if the array is in non-decreasing order
    for i in range(len(a) - 1):
        if a[i] > a[i + 1]:
            return False
    return True
