def solve(n, A):
    # Good sequences are constructed starting from the lowest positive integer.
    # They are marked by the "used" attribute, which indicates whether a position
    # has already been used.
    class Sequence:
        def __init__(self, A):
            self.A = A
            self.n = len(A)
            self.sequence = [False] * self.n
            self.used = [False] * self.n

        def get_available(self):
            # Finds the next available position in the sequence.
            for i in range(self.n):
                if not self.sequence[i] and not self.used[i]:
                    return i
            return -1

        def update(self, b):
            # Updates the sequence with the given value.
            self.sequence[b - 1] = True
            self.used[b - 1] = True

        def add(self, i):
            # Adds a new position to the sequence.
            self.sequence.append(False)
            self.used.append(False)
            self.n += 1
            self.sequence[i] = True
            self.used[i] = True

        def is_good(self):
            # Checks if the sequence is good.
            if self.n != len(set(self.A)):
                return False
            for i in range(self.n - 1):
                if self.A[i] == self.A[i + 1] or self.sequence[i] == self.sequence[i + 1]:
                    return False
                if self.A[i] > self.A[i + 1] or self.sequence[i] > self.sequence[i + 1]:
                    return False
            return True

        def print(self):
            # Prints the sequence.
            print(self.sequence)

    # Stores all the good sequences found.
    sequences = []
    # Stores the current sequence.
    s = Sequence(A)

    # Generates all the possible sequences.
    while True:
        # Finding the next available position in the sequence.
        i = s.get_available()
        # If there is no available position, then the sequence is finished.
        if i == -1:
            break
        # Updating the sequence with the next available position.
        s.update(i + 1)
        # Checking if the sequence is valid.
        if s.is_good():
            # If the sequence is valid, then it is added to the list.
            sequences.append(s)
            # If the sequence is optimal, it is marked as finished.
            if max([b for b in s.sequence if s.sequence[b - 1] for b in range(1, s.n)]) == s.n:
                break
    # Returns the minimum value of the third element of the last sequence.
    return min([b for b in sequences[-1].sequence if sequences[-1].sequence[b - 1] for b in range(1, sequences[-1].n)])

