def solve(maze):
    n, m = len(maze), len(maze[0])
    x1, y1, x2, y2 = maze[1]
    obstacles = []
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 1:
                obstacles.append((i, j))
    if len(obstacles) == 0:
        return 0
    visited = [[False] * m for _ in range(n)]
    def dfs(i, j):
        if visited[i][j]:
            return False
        visited[i][j] = True
        if i == x2 and j == y2:
            return True
        for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
            if 0 <= x < n and 0 <= y < m and maze[x][y] == 0 and dfs(x, y):
                return True
        return False
    count = 0
    for obstacle in obstacles:
        i, j = obstacle
        if not dfs(i, j):
            count += 1
    return count
