 import itertools

def solve(a):
    """
    Given a permutation of the elements of a list, determine if it is possible to sort the list
    in non-descending order by performing the indicated operation any number of times.

    Parameters:
    a (list): The permutation of the elements of the list

    Returns:
    bool: True if it is possible to sort the list in non-descending order, False otherwise
    """
    a = list(a)
    n = len(a)
    perm = list(range(1, n+1))
    for i in range(n-1):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                if a[i] > a[k]:
                    perm[i] = a[i] + a[j]
                    perm[k] = a[k] - a[i]
                else:
                    perm[j] = a[j] - a[k]
                    perm[k] = a[k] + a[j]
                    break
            if perm[i] > a[i]:
                break
        if perm[i] > a[i]:
            break
    return all(a[i] <= a[i+1] for i in range(n-1))

